import { Client } from 'ssh2';
import fs from 'fs';

const cmdFile = process.argv[2];
const cmd = fs.readFileSync(cmdFile, 'utf8');
const p = new PrismaClient();
const s = await p.server.findFirst({ where: { id: 'cmsecmdps0001hlp27ai6mr7c' } });
await p.$disconnect();
const host = s.ipAddress;
if (host !== '51.79.226.215') { console.error('IP ASSERT FAILED host=', host); process.exit(2); }
const password = decryptSecret(s.rootPasswordEnc);
const port = s.sshPort || 22;
const conn = new Client();
