import { PrismaClient } from '@prisma/client';
import { decryptSecret } from '../lib/crypto-box.ts';
import { Client } from 'ssh2';

const SERVER_ID = 'cmsecmdps0001hlp27ai6mr7c';
const EXPECT_IP = '51.79.226.215';

// Remote script: generate deploy key only if absent, ensure github known_host, print pubkey.
const REMOTE = [
  'set -e',
  'mkdir -p /root/.ssh && chmod 700 /root/.ssh',
  "if [ ! -f /root/.ssh/id_ed25519.pub ]; then ssh-keygen -t ed25519 -N '' -C 'nexis-app-studionexis-deploy' -f /root/.ssh/id_ed25519; fi",
  'ssh-keyscan -t ed25519 github.com >> /root/.ssh/known_hosts 2>/dev/null || true',
  'sort -u -o /root/.ssh/known_hosts /root/.ssh/known_hosts',
  'echo "===PUBKEY==="',
  'cat /root/.ssh/id_ed25519.pub',
].join('\n');

async function main() {
  const p = new PrismaClient();
  const s = await p.server.findFirst({ where: { id: SERVER_ID } });
  await p.$disconnect();

  if (!s) {
    console.error('SERVER NOT FOUND id=', SERVER_ID);
    process.exit(2);
  }
  const host = s.ipAddress;
  if (host !== EXPECT_IP) {
    console.error('IP ASSERT FAILED expected=', EXPECT_IP, 'got=', host);
    process.exit(2);
  }
  console.error('IP ASSERT OK: server', s.name, 'ip', host);

  const password = decryptSecret(s.rootPasswordEnc);
  if (!password) {
    console.error('DECRYPT FAILED: rootPasswordEnc could not be decrypted');
    process.exit(2);
  }
  const port = s.sshPort || 22;

  const conn = new Client();
  const code: number = await new Promise((resolve) => {
    conn
      .on('ready', () => {
        conn.exec(REMOTE, (err, stream) => {
          if (err) {
            console.error('EXEC ERR', err.message);
            return resolve(1);
          }
          stream
            .on('close', (c: number) => {
              conn.end();
              resolve(c);
            })
            .on('data', (d: Buffer) => process.stdout.write(d))
            .stderr.on('data', (d: Buffer) => process.stderr.write(d));
        });
      })
      .on('error', (e) => {
        console.error('CONN ERR', e.message);
        resolve(3);
      })
      .connect({ host, port, username: 'root', password, readyTimeout: 20000 });
  });
  process.exit(code);
}

main().catch((e) => {
  console.error('FATAL', e);
  process.exit(1);
});
